package vn.covie.checkout.application; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import vn.covie.catalog.model.*; import vn.covie.catalog.persistence.*; import vn.covie.checkout.api.dto.CheckoutPreviewRequest; import vn.covie.checkout.model.CheckoutSourceType; import vn.covie.merchants.persistence.*; import vn.covie.shared.web.*;
@Component public class DirectCheckoutCandidateResolver implements CheckoutCandidateResolver{private final LocationVariantRepository offers;private final VariantRepository variants;private final CatalogItemRepository catalog;private final MerchantLocationRepository locations;public DirectCheckoutCandidateResolver(LocationVariantRepository offers,VariantRepository variants,CatalogItemRepository catalog,MerchantLocationRepository locations){this.offers=offers;this.variants=variants;this.catalog=catalog;this.locations=locations;}public CheckoutSourceType supports(){return CheckoutSourceType.DIRECT;}public CheckoutCandidate resolve(UUID user,CheckoutPreviewRequest request){if(request.items()==null||request.items().isEmpty()||request.items().size()>50)throw invalid("DIRECT checkout requires 1 to 50 items.");Set<UUID> seen=new HashSet<>();List<CheckoutCandidateItem> result=new ArrayList<>();CatalogItemType type=null;UUID locationId=null;UUID merchantId=null;for(var raw:request.items()){if(raw==null||raw.locationVariantId()==null||raw.quantity()<1||!seen.add(raw.locationVariantId()))throw invalid("Invalid or duplicate checkout item.");var offer=offers.findUsableById(raw.locationVariantId()).orElseThrow(DirectCheckoutCandidateResolver::notFound);var variant=variants.findById(offer.getVariantId()).orElseThrow(DirectCheckoutCandidateResolver::notFound);var item=catalog.findById(variant.getCatalogItemId()).orElseThrow(DirectCheckoutCandidateResolver::notFound);if(type==null)type=item.getItemType();if(type!=item.getItemType()||(type==CatalogItemType.SERVICE&&raw.quantity()!=1))throw invalid("Checkout cannot mix item types.");if(locationId==null)locationId=offer.getMerchantLocationId();if(!locationId.equals(offer.getMerchantLocationId()))throw invalid("Checkout cannot mix locations.");merchantId=item.getMerchantProfileId();result.add(new CheckoutCandidateItem(offer.getId(),variant.getId(),item.getId(),raw.quantity()));}locations.findById(locationId).orElseThrow(DirectCheckoutCandidateResolver::notFound);return new CheckoutCandidate(CheckoutSourceType.DIRECT,user,merchantId,locationId,type,List.copyOf(result),null,null);}private static ApiException invalid(String m){return new ApiException(ErrorCode.CHECKOUT_SOURCE_INVALID,HttpStatus.UNPROCESSABLE_ENTITY,m);}private static ApiException notFound(){return new ApiException(ErrorCode.RESOURCE_NOT_FOUND,HttpStatus.NOT_FOUND,"Resource not found.");}}
